/* UI controller: keeps the approved prototype's navigation, palette and geometric markers. */
(() => {
'use strict';
const c=LT.core,p=LT.planning,imp=LT.importer,cloud=LT.cloud,sync=LT.sync;
const $=sel=>document.querySelector(sel), $$=sel=>Array.from(document.querySelectorAll(sel));
const esc=x=>String(x??'').replace(/[&<>"']/g,t=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[t]));
const hue=x=>/^#[0-9a-fA-F]{6}$/.test(x||'')?x:'#159e89';
const format=s=>new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short'}).format(c.dateOf(s));
const pct=n=>`${n.pct}%`;
const category=x=>x==='independent'?'Bağımsız':'Okul';
const rtype=x=>({book:'Kitap',video:'Video / çevrim içi ders',website:'Web sitesi',other:'Diğer'})[x]||'Kaynak';
const nowWeek=()=>c.monday();
let state=c.defaults(), page='home',courseId=null,resourceId=null,week=nowWeek(),theme=localStorage.getItem('lt_theme_v1')||'light',preview=null,previewResourceId=null,previewAccess=null,previewNotes=[];
let currentUser=null,mode='loading',revision=0,base=null,localDirty=false,syncing=false,syncTimer=null,conflictContext=null;
let isPlanMode=false,selectedNodes=new Set(),selectedWeekly=new Set(),highlightView=false,listView=false,archiveView=false,resourceFilter='all',reviewSelections=new Set(),authResult=null;
function toast(msg){const el=$('#toast');el.textContent=String(msg);el.classList.add('show');clearTimeout(toast._timer);toast._timer=setTimeout(()=>el.classList.remove('show'),2900);}
function localKey(){return mode==='demo'?'lt_demo_v1':`lt_account_${currentUser?.accountId||'none'}_v1`}
function persist(){sync.writeCache(localKey(),state,revision,base);}
function commit(){localDirty=true;p.snapshotWeeks(state);persist();render();if(mode==='cloud'){clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncNow(false),900)}}
function safeJob(fn){try{const promise=fn();if(promise?.then)promise.catch(e=>{console.error(e);toast(e.message||'İşlem tamamlanamadı')})}catch(e){console.error(e);toast(e.message||'İşlem tamamlanamadı')}}
function status(message){$('#syncStatus').textContent=message}
async function syncNow(force=true){if(mode!=='cloud'||syncing)return;if(!localDirty){if(force){syncing=true;try{await pullAndMerge()}catch(e){status('Bulut erişilemedi');throw e}finally{syncing=false}}return;}syncing=true;status('Eşitleniyor...');try{
  const sent=sync.clone(state);let response=await cloud.push(sent,revision);revision=Number(response.revision??revision+1);base=sent;localDirty=!sync.same(state,sent);persist();status(localDirty?'Yeni değişiklikler bekliyor':'Bulut güncel');if(localDirty)setTimeout(()=>syncNow(false),1500);
}catch(err){if(err.status===409||err.code==='revision_conflict'){await pullAndMerge();}else{status('Çevrim dışı · kayıt korundu');if(force)toast(err.message||'Bulut erişilemedi');}}
finally{syncing=false;}}
async function pullAndMerge(){const remote=await cloud.pull();const remoteState=remote.state||c.defaults(),remoteRevision=Number(remote.revision||0);c.validateState(remoteState);const result=sync.merge(base||c.defaults(),state,remoteState);revision=remoteRevision;base=sync.clone(remoteState);if(result.conflicts.length){conflictContext=result;status('Senkronizasyon çatışması');showConflict();return;}state=result.state;localDirty=!sync.same(state,remoteState);persist();status(localDirty?'Birleştirildi · eşitle':'Bulut güncel');render();if(localDirty)setTimeout(()=>syncNow(false),750);}
async function pullInitial(){const server=await cloud.pull(),remoteState=server.state||c.defaults();c.validateState(remoteState);const remoteRev=Number(server.revision||0),record=sync.useCache(localKey());if(record?.state){const merged=sync.merge(record.baseState||record.state,record.state,remoteState);state=merged.state;revision=remoteRev;base=sync.clone(remoteState);localDirty=!sync.same(state,remoteState);if(merged.conflicts.length){conflictContext=merged;status('Çakışma bulundu');showConflict();}else if(localDirty){await syncNow(false);}else status('Bulut güncel');}else{state=sync.clone(remoteState);revision=remoteRev;base=sync.clone(remoteState);localDirty=false;status('Bulut güncel');}const reviewChanged=p.snapshotWeeks(state);if(reviewChanged){localDirty=true;setTimeout(()=>syncNow(false),850)}persist();}
async function showConflict(){if(!conflictContext)return;const count=conflictContext.conflicts.length;openModal('Cihazlar arası değişiklik çatışması',`<div class="notice">${count} kayıt iki cihazda farklı değiştirildi. Hiçbir yerel değişiklik otomatik silinmedi. Devam etmeden önce JSON yedeği almanı öneririz.</div><div class="action-row"><button class="ghost-btn" data-action="export">JSON yedeği al</button></div><p class="muted-text">Çakışan kayıtlar: ${esc(conflictContext.conflicts.slice(0,10).map(x=>x.collection+': '+x.id).join(', '))}</p><div class="modal-footer"><button class="ghost-btn" data-action="resolve-conflict" data-choice="remote">Sunucudaki sürümü seç</button><button class="primary-btn" data-action="resolve-conflict" data-choice="local">Bu cihazdaki sürümü seç</button></div>`);}
function clearModal(){preview=null;previewResourceId=null;previewAccess=null;previewNotes=[];$('#modalBackdrop').classList.remove('show');}
function openModal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalBackdrop').classList.add('show');}
function field(label,name,value='',opts={}){const v=esc(value),type=opts.type||'text';return `<label>${esc(label)}${opts.options?`<select name="${name}">${opts.options.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(value)?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`:`<input name="${name}" type="${type}" value="${v}" ${opts.required?'required':''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''} ${opts.max?`maxlength="${opts.max}"`:''}>`}</label>`}
const colors=['#159e89','#8979a8','#d99a05','#4e93bf','#ca716a','#698e68'];
const colorField=value=>`<label>Renk<select name="color">${colors.map(h=>`<option value="${h}" ${h===value?'selected':''}>${h==='\#159e89'?'Yeşil':h==='\#8979a8'?'Mor':h==='\#d99a05'?'Sarı':h==='\#4e93bf'?'Mavi':h==='\#ca716a'?'Kırmızı':'Zeytin yeşili'}</option>`).join('')}</select></label>`;
function selectResourceOptions(course,value=''){return c.resources(state,course).map(r=>`<option value="${esc(r.id)}" ${r.id===value?'selected':''}>${esc(r.title)}</option>`).join('');}
function showCourseForm(id=null){const course=id&&c.byId(state,'courses',id);openModal(course?'Dersi düzenle':'Yeni ders',`<form class="form-fields" id="recordForm" data-kind="course" data-id="${esc(id||'')}">${field('Ders adı','name',course?.name||'',{required:true,max:120})}<div class="form-row">${field('Kategori','category',course?.category||'school',{options:[['school','Okul'],['independent','Bağımsız']]})}${colorField(course?.color||colors[c.courses(state).length%colors.length])}</div><div class="modal-footer"><button type="button" class="ghost-btn" data-action="close-modal">İptal</button><button class="primary-btn" type="submit">Kaydet</button></div></form>`)}
function showResourceForm(id=null,chosenCourse=null){const resource=id&&c.byId(state,'resources',id);if(!c.courses(state).length){toast('Önce bir ders oluşturun');showCourseForm();return;}openModal(resource?'Kaynağı düzenle':'Yeni kaynak',`<form class="form-fields" id="recordForm" data-kind="resource" data-id="${esc(id||'')}">${field('Kaynak adı','title',resource?.title||'',{required:true,max:200})}<div class="form-row">${field('Ders','courseId',resource?.courseId||chosenCourse||courseId||c.courses(state)[0].id,{options:c.courses(state).map(x=>[x.id,x.name])})}${field('Tür','type',resource?.type||'book',{options:[['book','Kitap / ders kitabı'],['video','Video / çevrim içi ders'],['website','Web sitesi'],['other','Diğer']]})}</div>${field('Kaynak URL (isteğe bağlı)','sourceUrl',resource?.sourceUrl||'',{placeholder:'https://...'})}<p class="muted-text">AI destekli içerik haritası isteğe bağlıdır. Sistem içerik uydurmaz. Kaynak eklendikten sonra JSON aktarımı yapabilirsin.</p><div class="modal-footer"><button type="button" class="ghost-btn" data-action="close-modal">İptal</button><button class="primary-btn" type="submit">Kaydet</button></div></form>`)}
function showNodeForm(parentId=null,id=null,resourceOverride=null){const node=id&&c.byId(state,'nodes',id);const rid=node?.resourceId||resourceOverride||resourceId;if(!rid){toast('Önce kaynak aç');return;}openModal(node?'İçeriği düzenle':'Yeni içerik',`<form class="form-fields" id="recordForm" data-kind="node" data-id="${esc(id||'')}" data-resource="${esc(rid)}" data-parent="${esc(parentId||'')}">${field('Başlık','title',node?.title||'',{required:true,max:500})}${field('İçerik türü','kind',node?.kind||'topic',{options:[['group','Başlık / bölüm'],['topic','Konu'],['quiz','Alıştırma / quiz'],['test','Test']]})}<div class="modal-footer"><button type="button" class="ghost-btn" data-action="close-modal">İptal</button><button class="primary-btn" type="submit">Kaydet</button></div></form>`)}
function renderHead(eyebrow,title,subtitle,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 class="page-title">${esc(title)}</h1><div class="page-sub">${esc(subtitle)}</div></div><div class="btn-row">${buttons}</div></div>`;}
function button(text,action,id='',className='ghost-btn'){return `<button class="${className}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${text}</button>`}
function progressBar(stats){return `<div class="bar"><span style="width:${stats.pct}%"></span></div>`}
function empty(text){return `<div class="empty-panel">${esc(text)}</div>`}
function titleFor(weekValue){return `${format(weekValue)} – ${format(c.weekEnd(weekValue))}`}
function weekOptions(selected){let ws=p.weeks(state);if(!ws.includes(selected))ws.push(selected);if(!ws.includes(nowWeek()))ws.push(nowWeek());ws.sort();return ws.map(w=>`<option value="${w}" ${w===selected?'selected':''}>${esc(titleFor(w))}</option>`).join('');}
function renderSidebar(){const nav=$('#sideCourses');nav.innerHTML=c.courses(state).filter(x=>!x.archivedAt||archiveView).map(x=>`<button data-course="${esc(x.id)}" class="${page==='courses'&&courseId===x.id?'active':''}"><i class="course-dot" style="--course-color:${hue(x.color)}"></i>${esc(x.name)}</button>`).join('');const result=p.rows(state,nowWeek());$('#sideWeekText').textContent=`${result.completedCount} / ${result.plannedCount} konu tamamlandı`;$('#sideWeekBar').style.width=result.completionPercentage+'%';$$('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));$('#breadcrumb').textContent=({home:'Genel Bakış',courses:'Derslerim',weekly:'Haftalık Plan',resources:'Kaynaklar',analytics:'İstatistikler',settings:'Ayarlar'})[page];$('.theme-toggle').textContent=theme==='light'?'☾ Koyu tema':'☀ Açık tema';}
function weekCard(w,index){const stats=p.rows(state,w);const current=w===nowWeek();return `<button class="home-week-progress-card ${current?'current':'later'}" data-week="${w}"><span class="home-week-card-top"><strong>${current?'Bu hafta':`Sonraki ${index}. hafta`}</strong><small>${esc(format(w))}</small></span><span class="home-week-card-value">${stats.plannedCount?stats.completionPercentage+'%':'—'}</span><span class="home-week-card-foot">${stats.completedCount}/${stats.plannedCount} konu</span></button>`;}
function home(){const total=c.totalStats(state),current=p.rows(state,nowWeek()),allCourses=c.courses(state).filter(x=>!x.archivedAt),weeks=[nowWeek(),c.addDays(nowWeek(),7),c.addDays(nowWeek(),14),c.addDays(nowWeek(),21)];const reviews=p.pendingReviews(state);
const courseRows=allCourses.map(course=>{const st=c.courseStats(state,course.id);return `<div class="home-course-block"><div class="home-course-head"><strong>${esc(course.name)}</strong><span>${st.done}/${st.total} · ${st.pct}%</span></div>${progressBar(st)}${c.resources(state,course.id).filter(r=>!r.archivedAt).map(r=>{let s=c.resourceStats(state,r.id);return `<div class="home-source-row"><span class="home-source-name">${esc(r.title)}</span>${progressBar(s)}<span class="home-source-count">${s.done}/${s.total}</span></div>`}).join('')}</div>`}).join('');
const tasks=current.rows.slice(0,8).map(x=>`<div class="task-card"><button class="node ${c.status(state,x.node.id)}" data-action="toggle-node" data-id="${esc(x.node.id)}" title="Durumu değiştir">${shape(x.node.kind,c.status(state,x.node.id))}</button><div class="task-copy"><strong>${esc(x.node.title)}</strong><small>${esc(x.course?.name||'')} · ${esc(x.resource?.title||'')}</small></div><span class="task-side">${x.complete?'Bitti':'Bekliyor'}</span></div>`).join('');
return renderHead('Your learning workspace','Genel Bakış','Ders, kitap ve dijital kaynaklarındaki ilerlemeyi tek yerden takip et.',button('＋ Ders ekle','add-course','','primary-btn'))+
 (reviews.length?reviews.slice(0,2).map(review=>reviewCard(review,true)).join(''):'')+
 `<div class="home-focus section-card"><div class="home-focus-copy"><div class="focus-kicker">Öğrenme ilerlemen</div><h2>${total.done} / ${total.total} takip konusu tamamlandı</h2><p>${allCourses.length} aktif ders · ${allCourses.reduce((v,x)=>v+c.resources(state,x.id).length,0)} kaynak · Tamamlanma, öğrenme düzeyi değildir.</p></div><div class="focus-ring-wrap"><div class="focus-ring" style="--progress:${total.pct}%"><div><strong>${total.pct}%</strong><small>Materyal</small></div></div></div></div>`+
 `<section class="section-card home-weekly-progress"><div class="section-head-row"><h3 class="section-title">Haftalık hedefler</h3>${button('Daha fazla','go-weekly','','text-link')}</div><div class="home-week-progress-grid">${weeks.map(weekCard).join('')}</div></section>`+
 `<div class="dashboard-grid home-main-grid"><section class="section-card"><div class="section-head-row"><h3 class="section-title">Ders ve kaynak ilerlemesi</h3><span class="muted-text">Kaynaklar bağımsız takip edilir</span></div>${courseRows||empty('Henüz ders yok. İlk dersini ekle.')}</section><section class="section-card"><div class="section-head-row"><h3 class="section-title">Bu haftanın planı</h3><span class="tag">${esc(titleFor(nowWeek()))}</span></div>${tasks||empty('Bu hafta için henüz konu seçmedin.')}${button('Haftalık planı aç','go-weekly','','soft-btn')}</section></div>`;
}
function shape(kind,status){const path=kind==='quiz'?'<path d="M12 2.5 21.5 12 12 21.5 2.5 12Z"/>':kind==='test'?'<path d="M6.5 2.5h11L21.5 12l-4 9.5h-11L2.5 12Z"/>':'<circle cx="12" cy="12" r="9.3"/>';return `<svg viewBox="0 0 24 24" aria-hidden="true">${path}</svg>${status==='completed'?'<span class="node-check" style="display:flex">✓</span>':''}`;}
function leafNode(n,grid=true){const status=c.status(state,n.id),assigned=p.active(state,n.id),isSelected=selectedNodes.has(n.id),highlight=state.settings.showHighlights&&assigned;const props=`data-action="toggle-node" data-id="${esc(n.id)}" title="${esc(n.title)} — ${status==='completed'?'Bitti':status==='progress'?'Devam ediyor':'Başlanmadı'}"`;const node=`<button class="node ${status} ${isSelected?'selected':''}" ${props} aria-label="${esc(n.title)}">${shape(n.kind,status)}</button>`;
if(!grid)return `<div class="topic-line">${node}<span class="topic-name">${esc(n.title)}</span><span class="tag">${esc(n.kind==='quiz'?'Quiz':n.kind==='test'?'Test':'Konu')}</span>${assigned?`<span class="topic-week-label">${esc(format(assigned.weekStart))}</span>`:''}</div>`;
return `<div class="topic-item ${highlight?'week-planned':''}" ${highlight?`style="--week-color:${hue(['#159e89','#8979a8','#d99a05','#4e93bf'][p.weeks(state).indexOf(assigned.weekStart)%4]||'#159e89')}"`:''}>${node}<span class="topic-caption">${esc(n.title)}</span>${assigned?`<span class="topic-week-label">${esc(format(assigned.weekStart))}</span>`:''}</div>`;
}
function renderBranch(treeNodes,depth=0){const out=[];for(const n of treeNodes){if(n.children?.length||n.kind==='group'){out.push(`<details class="branch" ${depth<1?'open':''}><summary><span class="branch-title">${esc(n.title)}</span><small>${c.counts(state,c.descendants(state,n.id)).pct}%</small><span class="actions-menu"><button data-action="new-child" data-id="${esc(n.id)}" title="Alt içerik ekle">＋</button><button data-action="edit-node" data-id="${esc(n.id)}" title="Düzenle">✎</button><button data-action="delete-node" data-id="${esc(n.id)}" title="Sil">×</button></span></summary><div class="branch-content">${renderBranch(n.children||[],depth+1)}</div></details>`);}else out.push(leafNode(n,!listView));}if(!out.length)return depth?'':empty('Henüz içerik yok. Yeni konu ekleyebilir veya AI JSON aktarabilirsin.');return listView?out.join(''):`<div class="topics-grid">${out.join('')}</div>`;}
function coursesPage(){let cs=c.courses(state).filter(x=>!x.archivedAt||archiveView);if(!cs.length)return renderHead('Organize your learning','Derslerim','Derslerini ve kaynaklarını birlikte yönet.',button('＋ Ders ekle','add-course','','primary-btn'))+empty('Henüz ders bulunmuyor. Ders oluşturarak başla.');if(!c.byId(state,'courses',courseId))courseId=cs[0].id;let course=c.byId(state,'courses',courseId);if(!course)return empty('Ders bulunamadı');const resources=c.resources(state,courseId).filter(r=>!r.archivedAt||archiveView);if(!resources.some(r=>r.id===resourceId))resourceId=resources[0]?.id||null;const selected=c.byId(state,'resources',resourceId);const stats=c.courseStats(state,courseId);
const courseTabs=`<div class="courses-top">${cs.map(co=>`<button class="ghost-btn btn-sm ${co.id===courseId?'active':''}" data-course="${esc(co.id)}">${esc(co.name)} <span class="progress-mini">${c.courseStats(state,co.id).pct}%</span></button>`).join('')}</div>`;
const sourceTabs=`<div class="source-switch">${resources.map(r=>`<button class="resource-map-tab ${r.id===resourceId?'active':''}" data-resource="${esc(r.id)}"><strong>${esc(r.title)}</strong><span class="source-pct">${c.resourceStats(state,r.id).pct}%</span></button>`).join('')}</div>`;
const controls=`<div class="toolbar"><div class="action-row">${button('＋ Bölüm / konu','add-node','','soft-btn')}${button('⇩ AI JSON aktar','import','','ghost-btn')}${button('✎ Kaynağı düzenle','edit-resource',resourceId)}${button('••• Ders ayarları','edit-course',courseId)}</div><div class="action-row"><button class="ghost-btn btn-sm" data-action="toggle-view">${listView?'▦ Izgara':'☷ Liste'}</button><button class="ghost-btn btn-sm ${isPlanMode?'active':''}" data-action="plan-mode">${isPlanMode?'Seçimi bitir':'＋ Planla'}</button><label class="week-map-toggle"><input type="checkbox" data-toggle="highlights" ${state.settings.showHighlights?'checked':''}> Haftalık planları göster</label></div></div>`;
const assignBar=isPlanMode?`<div class="bulkbar"><strong>${selectedNodes.size} konu seçildi</strong><select id="planTargetWeek">${weekOptions(week)}</select>${button('Seçilenleri planla','assign-selected','','primary-btn')}${button('Seçimi temizle','clear-select')}<small>Birden fazla konuyu seçebilirsin.</small></div>`:'';
const sourceContent=selected?`<div class="section-card"><div class="section-head-row"><h3 class="section-title">${esc(selected.title)} · ${c.resourceStats(state,selected.id).done}/${c.resourceStats(state,selected.id).total} tamamlandı</h3>${selected.sourceUrl?`<a class="text-link" href="${esc(selected.sourceUrl)}" target="_blank" rel="noopener noreferrer">Kaynağı aç</a>`:''}</div>${selected.sourceAccess==='partial'?`<div class="notice">Kısmi kaynak erişimi · ${esc((selected.sourceNotes||[]).join(' · ')||'Erişim sınırı bildirildi')}</div>`:''}${selected.sourceAccess==='unavailable'?`<div class="notice">Kaynağa erişilemedi; otomatik konu üretilmedi.</div>`:''}${renderBranch(c.tree(state,selected.id))}</div>`:empty('Bu derse henüz kaynak eklenmemiş. Kaynak ekleyip içerik haritasını oluştur.');
return renderHead('Your courses','Derslerim','Derslerin ve her kaynağın ilerlemesi ayrı ayrı hesaplanır.',button('＋ Ders ekle','add-course','','primary-btn')+button('＋ Kaynak ekle','add-resource','','soft-btn'))+courseTabs+`<div class="course-overview"><div><div class="course-heading"><h2>${esc(course.name)}</h2><span class="completion-pill">${stats.pct}% tamamlandı</span></div><div class="overview-note">${stats.done} / ${stats.total} takip konusu · ${esc(category(course.category))} ${course.archivedAt?' · Arşivlenmiş':''}</div></div><div class="action-row">${button('Ders ayarları','edit-course',course.id)}${button(course.archivedAt?'Arşivden çıkar':'Arşivle','archive-course',course.id)}${button('Dersi sil','delete-course',course.id)}</div></div>`+sourceTabs+controls+assignBar+sourceContent;
}
function resourcesPage(){const all=state.resources.filter(r=>!r.deletedAt&&(!r.archivedAt||archiveView)&&!!c.byId(state,'courses',r.courseId));return renderHead('Your learning materials','Kaynaklar','Kitaplarını ve video derslerini kaynak bazında organize et.',button('＋ Kaynak ekle','add-resource','','primary-btn'))+`<div class="toolbar"><div class="action-row"><select id="resourceFilter" class="inline-select"><option value="all">Tüm dersler</option>${c.courses(state).map(x=>`<option value="${esc(x.id)}" ${resourceFilter===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><label class="check-filter"><input type="checkbox" data-toggle="archive" ${archiveView?'checked':''}> Arşivlenenleri göster</label></div></div><div class="resource-grid">${all.filter(r=>resourceFilter==='all'||r.courseId===resourceFilter).map(r=>{const st=c.resourceStats(state,r.id),course=c.byId(state,'courses',r.courseId);return `<article class="resource-card ${r.archivedAt?'archived':''}"><div class="resource-icon">${r.type==='video'?'▶':r.type==='book'?'▤':'▧'}</div><h3>${esc(r.title)}</h3><p>${esc(course?.name||'')} · ${esc(rtype(r.type))}</p><div class="resource-foot"><span>${st.done}/${st.total} tamamlandı</span><span class="tag">${st.pct}%</span></div>${progressBar(st)}<div class="actions-menu"><button class="tiny-btn" data-action="open-resource" data-id="${esc(r.id)}">Harita</button><button class="tiny-btn" data-action="import" data-id="${esc(r.id)}">AI JSON</button><button class="tiny-btn" data-action="edit-resource" data-id="${esc(r.id)}">Düzenle</button><button class="tiny-btn" data-action="archive-resource" data-id="${esc(r.id)}">${r.archivedAt?'Geri al':'Arşivle'}</button><button class="tiny-btn" data-action="delete-resource" data-id="${esc(r.id)}">Sil</button></div></article>`}).join('')||empty('Filtreye uygun kaynak yok.')}</div>`;}
function reviewCard(review,compact=false){const unfinished=review.unfinishedNodeIds.filter(id=>!(review.resolvedNodeIds||[]).includes(id)).map(id=>state.nodes.find(n=>n.id===id)).filter(Boolean);return `<div class="review-card"><div class="section-head-row"><h3>${compact?'Önceki hafta değerlendirilmeyi bekliyor':'Hafta sonu değerlendirmesi'} · ${esc(titleFor(review.weekStart))}</h3><span class="tag">${review.completionPercentage}%</span></div><p>${review.completedCount} / ${review.plannedCount} planlanmış konu bitirildi · ${unfinished.length} konu tamamlanmadı. Geçmiş hafta oranı sonradan değişmez.</p><div class="week-review-list">${unfinished.slice(0,compact?3:200).map(n=>{const r=state.resources.find(x=>x.id===n.resourceId),co=state.courses.find(x=>x.id===r?.courseId);return `<label class="small-row"><input type="checkbox" data-review-node="${esc(n.id)}" ${reviewSelections.has(n.id)?'checked':''}> ${esc(co?.name||'')} — ${esc(r?.title||'')} — ${esc(n.title)}</label>`}).join('')}${compact&&unfinished.length>3?`<div class="inline-note">+ ${unfinished.length-3} konu daha</div>`:''}</div><div class="action-row"><select id="reviewTarget" class="inline-select" aria-label="Taşınacak hafta">${weekOptions(c.addDays(nowWeek(),7))}</select><button class="primary-btn btn-sm" data-action="review-move" data-id="${esc(review.id)}">Seçilenleri taşı</button><button class="ghost-btn btn-sm" data-action="review-defer" data-id="${esc(review.id)}">Ertele</button><button class="ghost-btn btn-sm" data-action="review-dismiss" data-id="${esc(review.id)}">Kapat</button></div></div>`;}
function weeklyPage(){const weeks=p.weeks(state),selected=week,weekRows=p.rows(state,selected);const current=selected===nowWeek();const past=c.weekEndInstant(selected)<=Date.now();let available=weeks.includes(nowWeek())?weeks:weeks.concat([nowWeek()]).sort();if(!available.includes(selected))available.push(selected);available.sort();
const panels=available.map(w=>{const st=p.rows(state,w);let days=Array.from({length:7},(_,i)=>{let day=c.addDays(w,i);return `<div class="calendar-day ${day===c.isoDay(new Date())?'today':''}"><span class="day-name">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'][i]}</span><strong class="day-number">${c.dateOf(day).getDate()}</strong></div>`}).join('');return `<button class="calendar-week ${w===selected?'active':''}" data-week="${w}"><div class="calendar-week-top"><span class="calendar-week-title">${esc(titleFor(w))}</span><span class="calendar-week-count">${st.completedCount}/${st.plannedCount} konu</span></div><div class="calendar-days">${days}</div><div class="calendar-week-bottom"><span class="calendar-week-subjects">${w===nowWeek()?'Bu hafta':w<nowWeek()?'Geçmiş hafta':'Gelecek hafta'}</span><span class="calendar-week-status">${st.plannedCount?st.completionPercentage+'%':'Plan yok'}</span></div><span class="calendar-week-progress"><i style="width:${st.completionPercentage}%"></i></span></button>`}).join('');
const taskRows=weekRows.rows.map(x=>`<div class="week-task ${x.complete?'done':''}"><input type="checkbox" data-week-node="${esc(x.node.id)}" ${selectedWeekly.has(x.node.id)?'checked':''} aria-label="Taşıma için seç"><button class="node ${c.status(state,x.node.id)}" data-action="toggle-node" data-id="${esc(x.node.id)}" title="Durumu değiştir">${shape(x.node.kind,c.status(state,x.node.id))}</button><div class="item-copy"><strong>${esc(x.node.title)}</strong><small>${esc(x.course?.name||'')} · ${esc(x.resource?.title||'')}</small></div>${button('Kaldır','unassign',x.node.id,'tiny-btn')}</div>`).join('');
const notes=state.weekNotes.find(n=>n.id===selected)?.text||'';
const history=state.reviews.filter(r=>r.weekStart===selected).map(r=>`<div class="notice"><strong>Hafta kapatıldı: ${r.completedCount}/${r.plannedCount} · ${r.completionPercentage}%</strong><div class="inline-note">Tarihsel sonuç sabittir. Bu hafta sonraki tamamlamalarla yükselmez.</div></div>`).join('');
return renderHead('Plan your learning','Haftalık Plan','Pazartesi–pazar haftaları · Kaynak haritasından veya topluca konu seç.',button('＋ İçerik ekle','weekly-add','','primary-btn'))+
 `<section class="plan-range-panel"><div class="plan-range-copy"><strong>Planlama dönemi</strong><span>Başlangıç ve bitiş tarihlerine göre haftalar oluşturulur.</span></div><div class="plan-range-fields"><label class="plan-date-field">Başlangıç<input type="date" id="planStart" value="${esc(state.settings.planStartDate)}"></label><label class="plan-date-field">Bitiş<input type="date" id="planEnd" value="${esc(state.settings.planEndDate)}"></label><button class="primary-btn" data-action="update-range">Takvimi güncelle</button></div></section>`+
 `<section class="calendar-panel"><div class="calendar-panel-head"><strong>Takvim</strong><span>Bir haftayı seçerek içeriğini görüntüle</span></div><div class="plan-calendar">${panels}</div></section>`+
 `<section class="section-card"><div class="week-head"><div><strong>${esc(titleFor(selected))}</strong><div class="muted-text">${past?'Geçmiş hafta · tarihsel tamamlanma sabit':'Bu haftaya planlanan içerikler'}</div></div><span class="tag">${weekRows.plannedCount} konu</span></div>${progressBar({pct:weekRows.completionPercentage})}<div class="week-progress-meta"><span>${weekRows.completedCount} / ${weekRows.plannedCount} tamamlandı</span><strong>${weekRows.completionPercentage}%</strong></div>${history}<div class="bulkbar"><strong>${selectedWeekly.size} seçildi</strong><select id="moveTarget">${weekOptions(c.addDays(nowWeek(),7))}</select>${button('Seçilenleri taşı','week-move','','soft-btn')}${button('Seçilenleri kaldır','week-remove')}</div>${taskRows||empty('Bu hafta için konu planlanmadı.')}<details class="week-notes"><summary>Hafta notları <span>İsteğe bağlı</span></summary><textarea id="weekNotesInput" placeholder="Haftanın notları...">${esc(notes)}</textarea></details></section>`;
}
function analyticsPage(){const total=c.totalStats(state),current=p.rows(state,nowWeek()),planned=state.assignments.filter(a=>a.status==='active').length,finished=state.reviews.filter(r=>r.status==='handled'||r.status==='dismissed').length;
const resources=c.courses(state).map(co=>{const stat=c.courseStats(state,co.id);return `<div class="analytics-course-block"><div class="analytics-course-title"><span>${esc(co.name)}</span><small>${stat.done}/${stat.total} · ${stat.pct}%</small></div>${progressBar(stat)}${c.resources(state,co.id).map(r=>{const s=c.resourceStats(state,r.id);return `<div class="analytics-source-row"><span class="source-name">${esc(r.title)}</span>${progressBar(s)}<span class="source-count">${s.done}/${s.total}</span></div>`}).join('')}</div>`}).join('');
const historyWeeks=Array.from({length:8},(_,i)=>c.addDays(nowWeek(),(i-7)*7));const historyData=historyWeeks.map(w=>{const cutoff=c.weekEndInstant(w),closed=cutoff<=Date.now();const completed=state.events.filter(e=>e.kind==='progress'&&e.to==='completed'&&new Date(e.at).getTime()>=c.dateOf(w).setHours(0,0,0,0)&&new Date(e.at).getTime()<cutoff).length;return {week:w,completed,closed};});const max=Math.max(1,...historyData.map(x=>x.completed));
const pastSnapshots=state.reviews.slice().sort((a,b)=>b.weekStart.localeCompare(a.weekStart));const snapshots=pastSnapshots.map(r=>`<div class="analytics-plan-metric"><span>${esc(titleFor(r.weekStart))}</span><strong>${r.completedCount}/${r.plannedCount} · ${r.completionPercentage}%</strong></div>`).join('');
return renderHead('Useful progress signals','İstatistikler','İşaretlediğin materyallerin gerçek kayıtlarına dayalı analizler.')+`<div class="stat-grid"><div class="stat-card"><div class="stat-label">Takip konuları</div><div class="stat-number">${total.total}</div></div><div class="stat-card"><div class="stat-label">Tamamlanan</div><div class="stat-number">${total.done}</div></div><div class="stat-card"><div class="stat-label">Genel ilerleme</div><div class="stat-number">${total.pct}%</div></div><div class="stat-card"><div class="stat-label">Aktif planlı</div><div class="stat-number">${planned}</div></div></div>`+
 `<div class="analytics-grid analytics-main-grid"><section class="section-card"><h3 class="section-title">Ders ve kaynak bazında ilerleme</h3>${resources||empty('Henüz ders yok.')}</section><section class="section-card"><h3 class="section-title">Bu haftanın planı</h3><div class="analytics-plan-metric"><span>Planlanan</span><strong>${current.plannedCount}</strong></div><div class="analytics-plan-metric"><span>Tamamlanan</span><strong>${current.completedCount}</strong></div><div class="analytics-plan-metric"><span>Oran</span><strong>${current.completionPercentage}%</strong></div><div class="analytics-plan-metric"><span>Tamamlanmış hafta incelemeleri</span><strong>${finished}</strong></div></section></div>`+
 `<div class="analytics-grid analytics-lower-grid" style="margin-top:14px"><section class="section-card"><h3 class="section-title">Tamamlanan konu olayları · son 8 hafta</h3>${state.events.some(e=>e.kind==='progress'&&e.to==='completed')?`<div class="history-bars">${historyData.map(x=>`<div class="history-col"><strong>${x.completed}</strong><div class="history-bar" style="height:${Math.max(1,Math.round(x.completed/max*125))}px"></div><span>${esc(format(x.week))}</span></div>`).join('')}</div>`:empty('Tarihli tamamlanma olayı henüz yok. Örnek grafik kullanılmıyor.')}<p class="inline-note">Bu grafik tamamlama işaretleme olaylarını gösterir; derste ustalaşmayı ölçmez.</p></section><section class="section-card"><h3 class="section-title">Kapanan haftaların performansı</h3>${snapshots||empty('Henüz kapanmış ve planlanmış hafta yok.')}</section></div>`+
 `<section class="section-card" style="margin-top:14px"><h3 class="section-title">Ders ve kaynakların tarihsel gelişimi · son 4 kapanmış hafta</h3>${c.courses(state).map(co=>{const historicalWeeks=Array.from({length:4},(_,i)=>c.addDays(nowWeek(),-(4-i)*7));const buildRow=(name,get)=>`<div class="source-line"><strong>${esc(name)}</strong><div class="action-row">${historicalWeeks.map(w=>{const val=get(c.weekEndInstant(w));return `<span class="tag" title="${esc(titleFor(w))}">${esc(format(w))}: ${val.total?val.pct+'%':'—'}</span>`}).join('')}</div></div>`;return buildRow(co.name,cutoff=>c.courseStatsAt(state,co.id,cutoff))+c.resources(state,co.id).map(r=>buildRow('↳ '+r.title,cutoff=>c.resourceStatsAt(state,r.id,cutoff))).join('')}).join('')||empty('Henüz tarihsel ilerleme verisi yok.')}</section><section class="section-card" style="margin-top:14px"><h3 class="section-title">Ölçüm tanımları</h3><p class="muted-text">Kaynak ilerlemesi = tamamlanan alt düzey konular / kaynak toplamı. Ders ilerlemesi = tüm kaynaklardaki toplam alt düzey konulara göre ağırlıklandırma. Haftalık ilerleme = o haftada biten / o haftaya atanmış konular. Ebeveyn bölüm başlıkları ayrıca sayılmaz. Çalışma süresi konu tamamlamasına katılmaz.</p></section>`;
}
function settingsPage(){const mappings=state.settings.mappings||{},session=currentUser;return renderHead('Personalize your workspace','Ayarlar & bağlantılar','Hesabını, yedeklerini ve görüntüleme tercihlerini yönet.')+`<div class="settings-grid"><section class="section-card"><h3 class="section-title">Hesap ve cihazlar</h3><p class="muted-text">${mode==='demo'?'Yerel deneme modu · veri yalnızca bu tarayıcıda':esc(session?.username||'')+' · Productivity App ile ortak hesap'}</p><div class="action-row">${button('Bulut eşitle','sync')}${button('Cihazları listele','devices')}${button('Diğer cihazları kapat','revoke-devices')}${button('Çıkış yap','logout','','soft-btn')}</div><p class="inline-note">Ortak oturum desteği gerçek Productivity App sunucusunda doğrulanmalıdır.</p></section><section class="section-card"><h3 class="section-title">Yedekleme</h3><p class="muted-text">Çalışma verilerini kendi JSON dosyana aktar veya dosyadan geri yükle.</p><div class="action-row">${button('JSON dışa aktar','export','','primary-btn')}<label class="ghost-btn">JSON içe aktar<input id="backupInput" type="file" accept=".json,application/json" style="display:none"></label></div><p class="inline-note">İçe aktarma mevcut verilerin yerine geçer. Önce yedek al.</p></section><section class="section-card"><h3 class="section-title">İlerleme görünümü</h3><label class="check-filter"><input type="checkbox" data-toggle="highlights" ${state.settings.showHighlights?'checked':''}> Haftalık planlanan konuları renkle vurgula</label><div class="source-line"><strong>Durumlar</strong><span class="tag good">Başlanmadı · Devam ediyor · Bitti</span></div></section><section class="section-card"><h3 class="section-title">Productivity App bağlantısı</h3><p class="muted-text">Çalışma süresi yalnızca ikincil göstergedir. Oturum verilerine erişim, kaynak depoya uygulanacak ayrı ve salt-okunur yetkili uç nokta gerektirir; henüz bağlanmadı.</p><div class="notice">Eşleştirme etiketleri saklanabilir; gerçek oturum süreleri bağlantı doğrulanana kadar görüntülenmez.</div>${Object.entries(mappings).map(([label,id])=>`<div class="source-line"><strong>${esc(label)}</strong><small>${esc(c.byId(state,'courses',id)?.name||'Eşleşme yok')}</small></div>`).join('')}${button('Etiket eşleştir','add-mapping','','soft-btn')}</section></div>`;}
function render(){const content=({home,courses:coursesPage,weekly:weeklyPage,resources:resourcesPage,analytics:analyticsPage,settings:settingsPage})[page];$('#mainContent').innerHTML=content();renderSidebar();document.documentElement.dataset.theme=theme;}
function navigate(next){page=next;$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'});}
function openImport(id=null){previewResourceId=id||resourceId;const r=c.byId(state,'resources',previewResourceId);if(!r){toast('Önce kaynak seçin');return;}const co=c.byId(state,'courses',r.courseId);const prompt=imp.createPrompt(r,co?.name);preview=imp.existingPreview(state,r.id);previewAccess=r.sourceAccess||'full';previewNotes=r.sourceNotes||[];openModal('AI içerik haritası · '+r.title,`<p class="muted-text">Kaynağı harici bir AI sohbetinde analiz ettir, JSON sonucunu buraya yapıştır. Gerçek içeriğe erişilemiyorsa hiçbir başlık uydurulmaz.</p><div class="action-row">${button('AI istemini kopyala','copy-prompt','','soft-btn')}<button class="ghost-btn" type="button" data-action="show-json">JSON formatı</button></div><textarea id="aiPrompt" class="editor-input" readonly style="min-height:90px;margin:12px 0">${esc(prompt)}</textarea><label class="field">AI JSON yanıtı<textarea id="importJSON" class="editor-input" rows="6" placeholder='{ "schema_version": 1, ... }'></textarea></label><div class="action-row">${button('JSON doğrula ve önizle','parse-import','','primary-btn')}${button('Mevcut haritayı düzenle','preview-current')}</div><p class="muted-text" id="importNotice">İçe aktarma öncesinde başlıkları düzenleyebilirsin.</p><div id="importPreview"></div>`);}
function findPreview(id,items=preview,parent=null){for(let i=0;i<(items||[]).length;i++){if(items[i]._key===id)return{item:items[i],items,index:i,parent};const found=findPreview(id,items[i].children,items[i]);if(found)return found}return null}
function previewNode(n){return `<div class="preview-node"><div class="preview-node-title"><input data-preview-title="${esc(n._key)}" aria-label="Konu adı" value="${esc(n.title)}"><button type="button" data-action="preview-add" data-id="${esc(n._key)}" title="Alt konu">＋</button><button type="button" data-action="preview-up" data-id="${esc(n._key)}" title="Yukarı">↑</button><button type="button" data-action="preview-down" data-id="${esc(n._key)}" title="Aşağı">↓</button><button type="button" data-action="preview-indent" data-id="${esc(n._key)}" title="Önceki başlığın altına taşı">⇥</button><button type="button" data-action="preview-outdent" data-id="${esc(n._key)}" title="Üst düzeye taşı">⇤</button><button type="button" data-action="preview-delete" data-id="${esc(n._key)}" title="Sil">×</button></div>${n.children.length?`<div class="preview-node-children">${n.children.map(previewNode).join('')}</div>`:''}</div>`}
function renderPreview(){const el=$('#importPreview');if(!el)return;el.innerHTML=`<div class="preview-box"><strong>Düzenlenebilir hiyerarşi önizlemesi</strong><p class="inline-note">Başlıkları değiştirebilir, alt konu ekleyebilir, silebilir ve sıralayabilirsin. Mevcut bir düğümün kimliği düzenleme sırasında korunur.</p><div class="preview-tree">${(preview||[]).map(previewNode).join('')||'<p class="muted-text">Yapı boş. Bir başlık ekleyebilirsin.</p>'}</div><div class="action-row" style="margin-top:10px">${button('＋ Kök başlık ekle','preview-add-root','','soft-btn')}${button('Onayla ve kaydet','confirm-import','','primary-btn')}</div></div>`;}
function showWeeklyAdd(){let choices=c.courses(state).flatMap(co=>c.resources(state,co.id).flatMap(r=>c.leaves(state,r.id).map(n=>({co,r,n}))));openModal('Haftaya konu ekle',`<p class="muted-text">Bir veya birden fazla konuyu işaretleyerek aynı haftaya ekleyebilirsin. Başka bir hafta seçmek mevcut aktif atamayı taşır ve eski kaydı saklar.</p><div class="form-fields">${field('Hedef hafta','target',week,{options:p.weeks(state).map(w=>[w,titleFor(w)])})}<div class="preview-tree" style="max-height:340px">${choices.map(({co,r,n})=>`<label class="small-row" style="display:flex;gap:9px;padding:7px;border-bottom:1px solid var(--border)"><input type="checkbox" data-weekly-add="${esc(n.id)}"><span><strong>${esc(n.title)}</strong><small class="muted-text">${esc(co.name)} · ${esc(r.title)}</small></span></label>`).join('')||empty('Planlanabilecek konu yok. Önce kaynağa içerik ekle.')}</div><div class="modal-footer">${button('İptal','close-modal')}${button('Seçilenleri planla','confirm-weekly-add','','primary-btn')}</div></div>`);}
async function onAction(action,element){const id=element.dataset.id||'',recordCourse=c.byId(state,'courses',id),recordResource=c.byId(state,'resources',id);switch(action){
case 'close-modal':clearModal();return;
case 'mobile-menu':$('#sidebar').classList.toggle('open');return;
case 'toggle-course-nav':$('#sideCourses').hidden=!$('#sideCourses').hidden;return;
case 'theme':theme=theme==='dark'?'light':'dark';localStorage.setItem('lt_theme_v1',theme);render();return;
case 'sync':await syncNow(true);if(mode==='demo')toast('Deneme modu yalnızca yerel saklama kullanır');return;
case 'reviews':{const reviews=state.reviews.filter(r=>!r.deletedAt).sort((a,b)=>b.weekStart.localeCompare(a.weekStart));openModal('Hafta değerlendirmeleri',reviews.length?reviews.map(x=>reviewCard(x)).join(''):empty('Henüz tamamlanmış bir haftanın değerlendirmesi yok.'));return}
case 'go-weekly':navigate('weekly');return;
case 'add-course':showCourseForm();return;
case 'edit-course':showCourseForm(id||courseId);return;
case 'archive-course':recordCourse.archivedAt=recordCourse.archivedAt?null:c.now();recordCourse.updatedAt=c.now();c.touch(state);commit();return;
case 'delete-course':if(confirm('Bu dersi ve bağlı bütün kaynaklarını silmek istediğine emin misin? İlişkili ilerleme kayıtları etkin görünümden kalkar.')){c.softDelete(state,'courses',id);courseId=null;resourceId=null;commit()}return;
case 'add-resource':showResourceForm(null,courseId);return;
case 'edit-resource':showResourceForm(id||resourceId);return;
case 'archive-resource':recordResource.archivedAt=recordResource.archivedAt?null:c.now();recordResource.updatedAt=c.now();c.touch(state);commit();return;
case 'delete-resource':if(confirm('Kaynağı ve hiyerarşisini kaldırmak istiyor musun?')){c.softDelete(state,'resources',id);if(resourceId===id)resourceId=null;commit()}return;
case 'open-resource':{const r=c.byId(state,'resources',id);courseId=r.courseId;resourceId=id;navigate('courses');return}
case 'add-node':showNodeForm(null,null,resourceId);return;
case 'new-child':showNodeForm(id,null,c.byId(state,'nodes',id)?.resourceId);return;
case 'edit-node':showNodeForm(null,id);return;
case 'delete-node':if(confirm('Bu başlığı ve tüm alt konuları kaldırmak istiyor musun?')){c.softDelete(state,'nodes',id);commit()}return;
case 'toggle-node':{const n=c.byId(state,'nodes',id);if(isPlanMode&&page==='courses'){selectedNodes.has(id)?selectedNodes.delete(id):selectedNodes.add(id);render();return;}const st=c.status(state,id);c.setStatus(state,id,st==='notstarted'?'progress':st==='progress'?'completed':'notstarted');commit();return;}
case 'toggle-view':listView=!listView;render();return;
case 'plan-mode':isPlanMode=!isPlanMode;selectedNodes.clear();render();return;
case 'clear-select':selectedNodes.clear();render();return;
case 'assign-selected':{if(!selectedNodes.size){toast('Önce konuları seç');return}const target=$('#planTargetWeek')?.value||week;for(const nodeId of selectedNodes)p.assign(state,nodeId,target);week=target;selectedNodes.clear();isPlanMode=false;commit();toast('Seçilen konular planlandı');return}
case 'weekly-add':showWeeklyAdd();return;
case 'confirm-weekly-add':{let selected=$$('[data-weekly-add]:checked').map(el=>el.dataset.weeklyAdd);const target=$('[name=target]')?.value;if(!selected.length||!target)throw Error('Hedef hafta ve en az bir konu seç');for(const nodeId of selected)p.assign(state,nodeId,target);week=target;clearModal();commit();return;}
case 'update-range':p.updateRange(state,$('#planStart').value,$('#planEnd').value);week=c.monday(state.settings.planStartDate);commit();return;
case 'unassign':p.remove(state,id);selectedWeekly.delete(id);commit();return;
case 'week-move':{const target=$('#moveTarget')?.value;if(!selectedWeekly.size)throw Error('Konuları işaretle');for(const nodeId of selectedWeekly)p.assign(state,nodeId,target);selectedWeekly.clear();commit();return;}
case 'week-remove':for(const nodeId of selectedWeekly)p.remove(state,nodeId);selectedWeekly.clear();commit();return;
case 'review-move':{const r=state.reviews.find(x=>x.id===id);if(!r)throw Error('Değerlendirme bulunamadı');const target=$('#reviewTarget')?.value;if(!target)throw Error('Hedef hafta seç');const chosen=[...reviewSelections].filter(x=>r.unfinishedNodeIds.includes(x));if(!chosen.length)throw Error('Taşınacak konuları seç');for(const nodeId of chosen){const n=c.byId(state,'nodes',nodeId);if(n)p.assign(state,nodeId,target)}r.resolvedNodeIds=[...new Set([...(r.resolvedNodeIds||[]),...chosen])];r.status=r.unfinishedNodeIds.every(nid=>r.resolvedNodeIds.includes(nid))?'handled':'pending';r.updatedAt=c.now();c.touch(state);reviewSelections.clear();clearModal();commit();return;}
case 'review-defer':p.editReview(state,id,'deferred');clearModal();commit();return;
case 'review-dismiss':p.editReview(state,id,'dismissed');clearModal();commit();return;
case 'import':openImport(id);return;
case 'copy-prompt':{const text=$('#aiPrompt')?.value;if(text)await navigator.clipboard.writeText(text);toast('AI istemi kopyalandı');return}
case 'show-json':{const sample={schema_version:1,resource_title:'Gerçek kaynak başlığı',source_access:'partial',notes:['Kaynağın yalnızca bir bölümü erişilebilirdi.'],structure:[]};$('#importJSON').value=JSON.stringify(sample,null,2);toast('Örnek şema girildi; gerçek kaynak bilgilerini AI yanıtıyla değiştir');return}
case 'parse-import':{const parsed=imp.parse($('#importJSON').value);preview=parsed.structure;previewAccess=parsed.source_access;previewNotes=parsed.notes;$('#importNotice').textContent=`Kaynak erişimi: ${parsed.source_access} · ${parsed.notes.join(' · ')||'Ek not yok'} · Kaynağı analiz etme durumunu kontrol et.`;renderPreview();return}
case 'preview-current':preview=imp.existingPreview(state,previewResourceId);previewAccess=c.byId(state,'resources',previewResourceId)?.sourceAccess||'full';previewNotes=c.byId(state,'resources',previewResourceId)?.sourceNotes||[];renderPreview();return;
case 'preview-add-root':preview.push({_key:c.uid(),title:'Yeni başlık',kind:'group',children:[]});renderPreview();return;
case 'preview-add':{const found=findPreview(id);if(found){found.item.children.push({_key:c.uid(),title:'Yeni alt konu',kind:'topic',children:[]});renderPreview()}return;}
case 'preview-delete':{const found=findPreview(id);if(found){found.items.splice(found.index,1);renderPreview()}return;}
case 'preview-up':case 'preview-down':{const found=findPreview(id);if(!found)return;const ix=found.index+(action==='preview-up'?-1:1);if(ix>=0&&ix<found.items.length){[found.items[found.index],found.items[ix]]=[found.items[ix],found.items[found.index]];renderPreview()}return;}
case 'preview-indent':{const found=findPreview(id);if(!found||found.index<1)return;const previous=found.items[found.index-1];found.items.splice(found.index,1);previous.children.push(found.item);renderPreview();return;}
case 'preview-outdent':{const found=findPreview(id);if(!found||!found.parent)return;const parentLocation=findPreview(found.parent._key);if(!parentLocation)return;found.items.splice(found.index,1);parentLocation.items.splice(parentLocation.index+1,0,found.item);renderPreview();return;}
case 'confirm-import':{if(!preview)throw Error('Önce bir önizleme oluştur');const n=imp.apply(state,previewResourceId,preview,previewAccess);const r=c.byId(state,'resources',previewResourceId);r.sourceNotes=previewNotes.slice();courseId=r.courseId;resourceId=r.id;clearModal();commit();navigate('courses');toast(`${n} içerik kaydedildi`);return;}
case 'add-mapping':{if(!c.courses(state).length)throw Error('Önce ders ekle');openModal('Productivity App etiket eşleştirmesi',`<form class="form-fields" id="recordForm" data-kind="mapping">${field('Oturum / ders etiketi','label','',{required:true,max:120})}${field('Learning Tracker dersi','courseId',c.courses(state)[0].id,{options:c.courses(state).map(co=>[co.id,co.name])})}<div class="modal-footer"><button class="primary-btn" type="submit">Eşleştirmeyi kaydet</button></div></form>`);return;}
case 'export':exportBackup();return;
case 'devices':{if(mode!=='cloud')throw Error('Cihaz yönetimi bulut hesabında kullanılır');const devices=await cloud.listDevices();openModal('Cihazlar',`<pre class="preview-box" style="white-space:pre-wrap">${esc(JSON.stringify(devices,null,2))}</pre>`);return;}
case 'revoke-devices':if(mode!=='cloud')throw Error('Bulut hesabı gerekli');if(confirm('Diğer cihazlardaki oturumları kapatmak istiyor musun?')){await cloud.revokeOthers();toast('Diğer cihazlar için kapatma isteği gönderildi')}return;
case 'logout':if(!confirm('Çalışma alanından çıkış yapılsın mı?'))return;if(mode==='cloud')await cloud.logout();currentUser=null;mode='none';state=c.defaults();$('#authGate').classList.remove('hidden');status('Oturum kapalı');return;
case 'resolve-conflict':{if(!conflictContext)return;state=sync.resolve(conflictContext.state,conflictContext.conflicts,element.dataset.choice);conflictContext=null;localDirty=true;persist();clearModal();render();await syncNow(true);return;}
default:throw Error('Bilinmeyen işlem: '+action);}}
function exportBackup(){const content=JSON.stringify({format:'learning-tracker-backup',exportedAt:c.now(),state},null,2);const blob=new Blob([content],{type:'application/json'});const u=URL.createObjectURL(blob);const link=document.createElement('a');link.href=u;link.download='learning-tracker-'+c.isoDay(new Date())+'.json';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('JSON yedeği hazırlandı');}
async function importBackup(file){if(!file||file.size>9_000_000)throw Error('Yedek 9 MB sınırını aşıyor');const data=JSON.parse(await file.text()),next=data?.state||data;c.validateState(next);if(!confirm('Geçerli çalışma verileri bu yedekle değiştirilecek. Devam edilsin mi?'))return;state=sync.clone(next);p.snapshotWeeks(state);commit();toast('Yedek geri yüklendi');}
function formSubmit(form){const values=Object.fromEntries(new FormData(form));const kind=form.dataset.kind,id=form.dataset.id,when=c.now();if(kind==='course'){if(id){c.editRecord(state,'courses',id,{name:values.name.trim(),category:values.category,color:hue(values.color)},['name','category','color'])}else{const added=c.addCourse(state,values.name,values.category,hue(values.color));courseId=added.id;resourceId=null;page='courses'}}
else if(kind==='resource'){if(id){const old=c.byId(state,'resources',id);if(!old)throw Error('Kaynak bulunamadı');if(!c.byId(state,'courses',values.courseId))throw Error('Ders bulunamadı');if(values.sourceUrl&&!/^https?:\/\//i.test(values.sourceUrl))throw Error('URL http(s) ile başlamalı');c.editRecord(state,'resources',id,{title:values.title.trim(),courseId:values.courseId,type:values.type,sourceUrl:values.sourceUrl},['title','courseId','type','sourceUrl'])}else{const r=c.addResource(state,values.courseId,values.title,values.type,values.sourceUrl);courseId=r.courseId;resourceId=r.id;page='courses'}}
else if(kind==='mapping'){const label=values.label.trim();if(!label||!c.byId(state,'courses',values.courseId))throw Error('Geçersiz eşleştirme');(state.settings.mappings ||= {})[label]=values.courseId;c.touch(state)}
else if(kind==='node'){if(id){c.editRecord(state,'nodes',id,{title:values.title.trim(),kind:values.kind},['title','kind'])}else{const siblings=state.nodes.filter(n=>n.resourceId===form.dataset.resource&&n.parentId===(form.dataset.parent||null)&&!n.deletedAt);state.nodes.push({id:c.uid(),resourceId:form.dataset.resource,parentId:form.dataset.parent||null,title:values.title.trim(),kind:values.kind,order:siblings.length,createdAt:when,updatedAt:when,deletedAt:null});c.touch(state)}}
clearModal();commit();}
async function startDemo(){mode='demo';currentUser=null;const cached=sync.useCache(localKey());state=cached?.state||c.defaults();revision=0;base=null;localDirty=false;p.snapshotWeeks(state);persist();$('#authGate').classList.add('hidden');status('Yerel deneme');render();}
async function startCloud(user){mode='cloud';currentUser=user;await pullInitial();$('#authGate').classList.add('hidden');render();}
async function bootstrap(){const msg=$('#authStatus');msg.textContent=cloud.configured()?'Productivity App hesabınla giriş yap.':'Bulut bağlantısı henüz yapılandırılmamış. Yerel çalışma alanını deneyebilirsin.';if(!cloud.configured())return;try{const user=await cloud.me();if(user)await startCloud(user)}catch(err){msg.textContent='Oturum doğrulanamadı: '+err.message+' · Yerel deneme modu kullanılabilir.';}}
async function authLogin(form){const values=Object.fromEntries(new FormData(form));const user=await cloud.login(values.username.trim(),values.magicPhrase.trim(),values.accessCode,!!values.remember);await startCloud(user);toast('Giriş yapıldı');}
async function authSignup(form){const vals=Object.fromEntries(new FormData(form));if(vals.accessCode!==vals.confirmCode)throw Error('Erişim kodları uyuşmuyor');const output=await cloud.signup(vals.accessCode),id=cloud.identity(output);if(!id.username||!id.magicPhrase)throw Error('Mevcut signup API beklenen kimlik bilgilerini döndürmedi; sunucu sözleşmesi kontrol edilmeli');authResult={username:id.username,magicPhrase:id.magicPhrase,accessCode:vals.accessCode};$('#signupForm').classList.add('hidden');$('#signupCredentials').classList.remove('hidden');$('#signupCredentials').innerHTML=`<div class="preview-box"><h3>Yeni hesabının bilgileri</h3><p><strong>Kullanıcı adı:</strong> ${esc(id.username)}</p><p><strong>Sihirli ifade:</strong> ${esc(id.magicPhrase)}</p><p><strong>Erişim kodu:</strong> ${esc(vals.accessCode)}</p><p class="status-warn">Bu bilgiler tekrar gösterilmeyebilir. Güvenli bir yere kaydet.</p><label class="check-row" style="display:flex;gap:8px"><input id="savedCredentials" type="checkbox"> Bilgileri kaydettim</label><button class="primary-btn" data-action="signup-finish" type="button">Kaydettim · giriş yap</button></div>`;}
async function finishSignup(){if(!$('#savedCredentials')?.checked)throw Error('Önce hesap bilgilerini sakladığını onayla');const user=await cloud.login(authResult.username,authResult.magicPhrase,authResult.accessCode,true);authResult=null;await startCloud(user);}
// All event listeners are attached once; rendering never stacks handlers.
document.addEventListener('click',event=>{const el=event.target.closest('[data-action],[data-page],[data-course],[data-resource],[data-week],[data-auth-tab]');if(!el)return;if(el.dataset.action){event.preventDefault();event.stopPropagation();if(el.dataset.action==='signup-finish'){safeJob(finishSignup);return}safeJob(()=>onAction(el.dataset.action,el));return;}if(el.dataset.page){navigate(el.dataset.page);return}if(el.dataset.course){courseId=el.dataset.course;resourceId=null;navigate('courses');return}if(el.dataset.resource){resourceId=el.dataset.resource;render();return}if(el.dataset.week){week=el.dataset.week;selectedWeekly.clear();navigate('weekly');return}if(el.dataset.authTab){$$('[data-auth-tab]').forEach(e=>e.classList.toggle('active',e===el));$('#loginForm').classList.toggle('hidden',el.dataset.authTab!=='login');$('#signupForm').classList.toggle('hidden',el.dataset.authTab!=='signup');return;}});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-toggle=highlights]')){state.settings.showHighlights=t.checked;commit()}else if(t.matches('[data-toggle=archive]')){archiveView=t.checked;render()}else if(t.matches('#resourceFilter')){resourceFilter=t.value;render()}else if(t.matches('[data-week-node]')){t.checked?selectedWeekly.add(t.dataset.weekNode):selectedWeekly.delete(t.dataset.weekNode);render()}else if(t.matches('[data-review-node]')){t.checked?reviewSelections.add(t.dataset.reviewNode):reviewSelections.delete(t.dataset.reviewNode);}else if(t.matches('#backupInput'))safeJob(()=>importBackup(t.files[0]));});
document.addEventListener('input',e=>{const t=e.target;if(t.matches('[data-preview-title]')){const found=findPreview(t.dataset.previewTitle);if(found)found.item.title=t.value;}else if(t.matches('#weekNotesInput')){const id=week;let obj=state.weekNotes.find(n=>n.id===id);if(!obj){obj={id,text:'',updatedAt:c.now()};state.weekNotes.push(obj)}obj.text=t.value;obj.updatedAt=c.now();c.touch(state);localDirty=true;persist();clearTimeout(syncTimer);if(mode==='cloud')syncTimer=setTimeout(()=>syncNow(false),1300);}});
document.addEventListener('submit',e=>{if(!['recordForm','loginForm','signupForm'].includes(e.target.id))return;e.preventDefault();const form=e.target;safeJob(()=>form.id==='recordForm'?formSubmit(form):form.id==='loginForm'?authLogin(form):authSignup(form));});
$('#demoBtn').addEventListener('click',()=>safeJob(startDemo));$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))clearModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modalBackdrop').classList.contains('show'))clearModal()});window.addEventListener('online',()=>{if(mode==='cloud')safeJob(()=>syncNow(true))});
bootstrap();
})();
